#include <Arduino.h>

// Motor specifications
const float STEP_ANGLE_DEG = 1.8;
const int STEPS_PER_REV = (int)(360.0 / STEP_ANGLE_DEG + 0.5);

const byte MOTOR_PINS[4] = {8, 9, 10, 11};
const byte POT_PIN = A0;
const byte BUTTON_PIN = 2;
const byte DEBUG_PIN = 13;

const int SEQ_LEN = 4;
const int NUM_PINS = 4;

const byte SEQ[SEQ_LEN][NUM_PINS] = {
  {HIGH, LOW,  HIGH, LOW },
  {LOW,  HIGH, HIGH, LOW },
  {LOW,  HIGH, LOW,  HIGH},
  {HIGH, LOW,  LOW,  HIGH}
};

const int MIN_DELAY_MS = 2;
const int MAX_DELAY_MS = 20;
const unsigned long PAUSE_MS = 1000;
const unsigned long DEBOUNCE_MS = 50;

// Automatic motion states
enum MotionState { CW, PAUSE, CCW };
MotionState state = CW;

int stepIndex = 0;
int stepsDone = 0;

// Button reverses physical direction
bool manualReverse = false;

// Timing
unsigned long lastStepTime = 0;
unsigned long pauseStartTime = 0;

// Debounce
bool lastReading = HIGH;
bool stableButton = HIGH;
unsigned long lastDebounceTime = 0;

void applyStep() {
  for (int i = 0; i < NUM_PINS; i++) {
    digitalWrite(MOTOR_PINS[i], SEQ[stepIndex][i]);
  }
}

unsigned int getStepDelay() {
  int value = analogRead(POT_PIN);

  return map(value, 0, 1023,
             MAX_DELAY_MS, MIN_DELAY_MS);
}

void checkButton() {
  bool reading = digitalRead(BUTTON_PIN);
  unsigned long now = millis();

  if (reading != lastReading) {
    lastDebounceTime = now;
  }

  if (now - lastDebounceTime >= DEBOUNCE_MS) {
    if (reading != stableButton) {
      stableButton = reading;

      if (stableButton == LOW) {
        manualReverse = !manualReverse;

        // A new full revolution after changing direction
        if (state != PAUSE) {
          stepsDone = 0;
        }
      }
    }
  }

  lastReading = reading;
}

void setup() {
  for (int i = 0; i < NUM_PINS; i++) {
    pinMode(MOTOR_PINS[i], OUTPUT);
  }

  pinMode(POT_PIN, INPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(DEBUG_PIN, OUTPUT);

  applyStep();
  lastStepTime = millis();
}

void loop() {
  checkButton();

  unsigned long now = millis();

  // After CW, pause for exactly 1 second
  if (state == PAUSE) {
    if (now - pauseStartTime >= PAUSE_MS) {
      state = CCW;
      stepsDone = 0;
      lastStepTime = now - getStepDelay();
    }
    return;
  }

  unsigned int interval = getStepDelay();

  if (now - lastStepTime < interval) {
    return;
  }

  lastStepTime = now;

  // Automatic direction
  int dir = (state == CW) ? 1 : -1;

  // Manual reversal
  if (manualReverse) {
    dir = -dir;
  }

  // D13 indicates the actual commanded direction
  digitalWrite(DEBUG_PIN, dir == -1 ? HIGH : LOW);

  // Execute a full step
  stepIndex = (stepIndex + dir + SEQ_LEN) % SEQ_LEN;
  applyStep();

  stepsDone++;

  if (stepsDone >= STEPS_PER_REV) {
    stepsDone = 0;

    if (state == CW) {
      // Finished clockwise revolution
      state = PAUSE;
      pauseStartTime = now;
    } else {
      // Finished counterclockwise revolution
      // Repeat immediately
      state = CW;
    }
  }
}
